import { useEffect, useMemo, useState } from 'react';
import { BookOpen } from 'lucide-react';
import type { Player } from '@/types/player';
import { cn } from '@/lib/utils';
import SectionIntro from './SectionIntro';
import TeamLogo from '../brand/TeamLogo';

// The in-game record board (the coach's club only) beside the same records across the whole league
// (public/data/league/records.json, generated by scripts/league_records.py).

interface LeagueEntry { value: number; mark: string; player: string; pos?: string; season?: string; club?: boolean }
interface BoardRow {
  record: string;
  scope: 'career' | 'season' | 'game' | 'other';
  club: { mark: string; value: number | null; holder: string; year: string };
  league: { value: number; mark: string; top: LeagueEntry[]; basis: string; clubHolds: boolean } | null;
  broken?: boolean;
}
interface BoardFile { seasonsFrom: string | null; seasonsTo: string | null; records: BoardRow[] }

let cache: Promise<BoardFile | null> | null = null;
const loadBoard = () =>
  (cache ??= fetch(`${import.meta.env.BASE_URL}data/league/records.json`)
    .then((r) => (r.ok ? (r.json() as Promise<BoardFile>) : null))
    .catch(() => null));

type Filter = 'all' | 'broken' | 'held';
const SCOPES: { id: BoardRow['scope']; label: string }[] = [
  { id: 'career', label: 'Career' },
  { id: 'season', label: 'Season' },
];

const Holder = ({ e, byName, onSelect }: { e: LeagueEntry; byName: Map<string, Player>; onSelect: (p: Player) => void }) => {
  const p = e.club ? undefined : byName.get(e.player);
  const label = (
    <span className="flex min-w-0 items-center gap-1.5">
      {p?.team && <TeamLogo team={p.team} size={16} decorative backed />}
      <span className="truncate">{e.player}</span>
      {e.season && <span className="shrink-0 font-mono text-[10px] text-muted-foreground">{e.season}</span>}
    </span>
  );
  return p ? (
    <button type="button" onClick={() => onSelect(p)} className="min-w-0 text-left hover:text-gold" aria-label={`Open ${e.player}`}>
      {label}
    </button>
  ) : (
    label
  );
};

const Row = ({ r, byName, onSelect }: { r: BoardRow; byName: Map<string, Player>; onSelect: (p: Player) => void }) => {
  const L = r.league!;
  const lead = L.top[0];
  return (
    <li
      className={cn(
        'grid grid-cols-1 gap-2 rounded-lg border bg-panel p-3 sm:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)_minmax(0,1fr)] sm:items-center',
        r.broken ? 'border-flag/60' : 'border-line',
      )}
    >
      <div className="flex min-w-0 items-center justify-between gap-2 sm:block">
        <span className="font-display text-sm font-bold uppercase tracking-wide text-chalk">{r.record}</span>
        {r.broken ? (
          <span className="shrink-0 rounded bg-flag/20 px-1.5 py-0.5 font-pixel text-[8px] uppercase text-flag sm:mt-1 sm:inline-block">Beaten league-wide</span>
        ) : (
          <span className="shrink-0 rounded bg-gold/15 px-1.5 py-0.5 font-pixel text-[8px] uppercase text-gold sm:mt-1 sm:inline-block">League record</span>
        )}
      </div>
      <div className="min-w-0">
        <span className="block font-pixel text-[8px] uppercase text-muted-foreground">Club</span>
        <span className="block font-display text-xl font-extrabold leading-tight tabular-nums text-gold">{r.club.mark}</span>
        <span className="flex min-w-0 gap-1.5 text-xs text-secondary-foreground">
          <span className="truncate">{r.club.holder}</span>
          <span className="shrink-0 font-mono text-[10px] text-muted-foreground">{r.club.year}</span>
        </span>
      </div>
      <div className="min-w-0">
        <span className="block font-pixel text-[8px] uppercase text-muted-foreground">League</span>
        <span className={cn('block font-display text-xl font-extrabold leading-tight tabular-nums', r.broken ? 'text-flag' : 'text-chalk')}>{L.mark}</span>
        <span className="block text-xs text-secondary-foreground">
          {L.clubHolds ? <span className="text-muted-foreground">The club record stands</span> : <Holder e={lead} byName={byName} onSelect={onSelect} />}
        </span>
        {L.top.length > 1 && (
          <span className="mt-1 block space-y-0.5 text-[11px] text-muted-foreground">
            {L.top.slice(1).map((e, i) => (
              <span key={`${e.player}-${e.season ?? ''}`} className="flex min-w-0 items-center gap-1.5">
                <span className="shrink-0 font-mono tabular-nums">#{i + 2} {e.mark}</span>
                <Holder e={e} byName={byName} onSelect={onSelect} />
              </span>
            ))}
          </span>
        )}
      </div>
    </li>
  );
};

/** The club's record board next to the league-wide marks, career and season. */
const RecordBoard = ({ players, onSelect }: { players: Player[]; onSelect: (p: Player) => void }) => {
  const [data, setData] = useState<BoardFile | null>(null);
  const [scope, setScope] = useState<BoardRow['scope']>('career');
  const [filter, setFilter] = useState<Filter>('all');
  useEffect(() => {
    let live = true;
    loadBoard().then((d) => live && setData(d));
    return () => {
      live = false;
    };
  }, []);
  const byName = useMemo(() => new Map(players.map((p) => [p.name, p])), [players]);
  const rows = useMemo(() => (data?.records ?? []).filter((r) => r.league), [data]);
  if (!rows.length) return null;
  const broken = rows.filter((r) => r.broken).length;
  const shown = rows.filter((r) => r.scope === scope && (filter === 'all' || (filter === 'broken' ? r.broken : !r.broken)));
  const chip = (on: boolean) =>
    cn('rounded-full border px-3 py-1 font-display text-xs font-bold uppercase tracking-wide', on ? 'border-gold bg-gold text-night' : 'border-line bg-night/60 text-secondary-foreground');
  return (
    <section id="record-board" aria-labelledby="record-board-title" className="scroll-mt-20 space-y-3">
      <h2 id="record-board-title" className="section-title text-2xl">
        <BookOpen className="h-5 w-5 text-gold" aria-hidden="true" />
        Record Board
      </h2>
      <SectionIntro id="record-board" takeaway={`${broken} of ${rows.length} club records have been beaten somewhere in the league.`}>
        The game&apos;s record board only counts games played for Skura&apos;s club. Next to each club record: the best mark across the whole
        league, from every career card and every season since {data?.seasonsFrom ?? 'the first snapshot'} (players tracked at the time).
      </SectionIntro>
      <div className="flex flex-wrap gap-2" role="group" aria-label="Record board filters">
        {SCOPES.map((s) => (
          <button key={s.id} type="button" className={chip(scope === s.id)} aria-pressed={scope === s.id} onClick={() => setScope(s.id)}>
            {s.label}
          </button>
        ))}
        <span className="mx-1 w-px self-stretch bg-line" aria-hidden="true" />
        {(['all', 'broken', 'held'] as Filter[]).map((f) => (
          <button key={f} type="button" className={chip(filter === f)} aria-pressed={filter === f} onClick={() => setFilter(f)}>
            {f === 'all' ? 'All' : f === 'broken' ? 'Beaten' : 'Still the club'}
          </button>
        ))}
      </div>
      {shown.length ? (
        <ul className="space-y-2">
          {shown.map((r) => (
            <Row key={r.record} r={r} byName={byName} onSelect={onSelect} />
          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted-foreground">None here.</p>
      )}
    </section>
  );
};

export default RecordBoard;
